SELECT COUNT(*) AS appointment_count, COUNT_IF(d.sk_patient_id IS NULL) AS missing_dev_key, COUNT_IF(p.sk_patient_id IS NULL) AS missing_prod_key, COUNT_IF(d.sk_patient_id IS NULL AND s.sk_patient_id IS NOT NULL) AS missing_dev_with_patient_key, COUNT_IF(d.sk_patient_id IS DISTINCT FROM p.sk_patient_id) AS dev_prod_key_differences FROM DEV__STAGING.OLIDS.STG_OLIDS_APPOINTMENT a LEFT JOIN DEV__REPORTING.OLIDS_PERSON_DEMOGRAPHICS.DIM_PERSON_PSEUDO d ON a.person_id=d.person_id LEFT JOIN REPORTING.OLIDS_PERSON_DEMOGRAPHICS.DIM_PERSON_PSEUDO p ON a.person_id=p.person_id LEFT JOIN DEV__STAGING.OLIDS.STG_OLIDS_PATIENT s ON a.patient_id=s.id;
